    "stageTitle": "14. [Pilar 3: Nonverbal] Spatial Confidence (Postur & Penggunaan Ruang)",
    "content": "**🔗 Korelasi dengan Bahasa Tubuh:** Selain keselarasan gerakan dengan lawan bicara (*mirroring* di Bagian 13), cara seseorang menempati dan menggunakan ruang di sekitarnya (**Spatial Confidence**) memberikan petunjuk langsung mengenai tingkat kepercayaan diri dan dominasi maupun rasa aman yang ia rasakan saat itu.\n\n**Perbandingan Pola Postur:** Tingkat kenyamanan seseorang sangat terbaca dari sikap tubuhnya:\n• **(1) Pola Percaya Diri & Nyaman:** Duduk atau berdiri dengan postur tegak, menggunakan gestur tangan yang lebih terbuka, tidak membatasi gerakan tubuh secara kaku, dan mempertahankan posisi yang stabil.\n• **(2) Pola Terintimidasi & Tidak Nyaman:** Membungkukkan badan, menarik bahu ke dalam, menyilangkan tangan menutup dada, dan membuat ukuran tubuhnya terlihat lebih kecil.\n\n**Intinya:** ==Perhatikan apakah seseorang memperluas atau justru mengecilkan ruang tubuhnya untuk membaca tingkat kepercayaan diri dan kenyamanannya di lingkungan sosial.==",
