    "stageTitle": "15. [Pilar 3: Nonverbal] Pola Bicara (Speech Patterns) & Penampilan",
    "content": "**🔗 Penutup Pilar 3 (Nonverbal):** Melengkapi sinyal tubuh dan wajah (Bagian 11–14), komunikasi nonverbal juga terpancar melalui **cara seseorang berbicara (paralinguistik)** serta **pakaian/penampilan** yang ia pilih.\n\n**1. Speech Patterns (Pola Berbicara):** Perhatikan 4 indikator suara:\n• **(a) Kecepatan berbicara:** Orang gugup cenderung bicara terlalu cepat.\n• **(b) Kejelasan suara:** Orang percaya diri berbicara lebih jelas dan stabil.\n• **(c) Keraguan:** Terlalu banyak jeda atau tersendat menunjukkan ketidaknyamanan/beban berpikir.\n• **(d) Perubahan intonasi:** Nada suara yang mendadak naik/turun menandakan pergeseran emosi.\n\n**2. Clothing & Appearance (Penampilan):** Pakaian adalah bentuk komunikasi sosial tentang identitas dan bagaimana seseorang ingin dipersepsikan. *Contoh:* Seseorang yang mengenakan pakaian sangat formal di acara santai mungkin ingin terlihat menonjol, menunjukkan status (*Esteem* pada Pilar 2), atau memberi kesan profesional.\n\n**Intinya:** ==Suara dan penampilan adalah perpanjangan dari kondisi emosional dan identitas diri, namun wajib selalu diukur terhadap kebiasaan pribadi (baseline) dan budaya/konteksnya (Pilar 1).==",
