    "stageId": 16,
    "stageTitle": "16. [Pilar 4: Deteksi Kebohongan] Mengapa Jangan Langsung Mengonfrontasi",
    "content": "**🔗 Jembatan Pilar 1–3 ke Pilar 4 (Verifikasi):** Setelah melihat sinyal stres atau ketidaksesuaian ekspresi (Pilar 3), kita mungkin mencurigai seseorang sedang berbohong. Namun Patrick King menegaskan: **mendeteksi kebohongan tidak bisa hanya mengandalkan bahasa tubuh**, karena ada pembohong yang tampak gugup, tetapi ada pula yang sangat tenang dan percaya diri. Oleh karena itu, strategi terbaik di **Pilar 4** bukanlah menebak dari gerakan tubuh semata, melainkan **menguji bagaimana ia membangun dan mempertahankan ceritanya**.\n\nPrinsip pertama: **Jangan langsung mengonfrontasi atau menuduh bahwa ceritanya tidak masuk akal.** Sebaliknya, biarkan ia berbicara lebih banyak. Mengapa? Karena mempertahankan cerita karangan membutuhkan **usaha mental (cognitive load) yang besar**. Semakin banyak detail yang harus ia ciptakan, semakin besar peluang munculnya celah ketidakkonsistenan.\n\n**Contoh Kasus Nyata:** Jika seseorang mengaku pergi ke sebuah kafe kemarin dan Anda meragukannya, jangan langsung menyanggah. Tanyakan dengan santai: *\"Apa yang kamu pesan? Bagaimana suasana kafenya? Apa yang terjadi waktu kamu di sana?\"*\n\n**Intinya:** ==Jangan membuat pembohong langsung menutup diri dengan tuduhan; biarkan ia berbicara panjang lebar agar beban mental mengarang cerita membuka ketidakkonsistenannya sendiri.==",
