    "stageId": 17,
    "stageTitle": "17. [Pilar 4: Deteksi Kebohongan] Open-Ended Questions Lanjut ke Specific Questions",
    "content": "**🔗 Korelasi Strategi Bertanya:** Untuk menjalankan prinsip \"membiarkan orang berbicara lebih banyak\" (Bagian 16), kita menggunakan kombinasi dua jenis pertanyaan secara berurutan: mulai dari **Open-Ended Questions (Pertanyaan Terbuka)** lalu dikunci dengan **Specific Questions (Pertanyaan Spesifik)**.\n\n**Langkah 1 — Open-Ended Questions:** Bandingkan pertanyaan tertutup *\"Apakah kamu pergi ke kafe kemarin?\"* (yang hanya butuh jawaban mudah \"Ya/Tidak\") dengan pertanyaan terbuka *\"Ceritakan bagaimana kegiatanmu kemarin.\"* Pertanyaan terbuka memaksa lawan bicara menyusun kronologi, aktivitas, dan detail cerita secara luas.\n\n**Langkah 2 — Specific Questions:** Setelah ia memberikan gambaran umum di kafe, masuklah ke detail mikro yang sulit disiapkan sebelumnya: *\"Musik apa yang sedang diputar di sana? Kamu duduk di bagian mana? Apa yang kamu pesan? Siapa saja yang ada di sana?\"*\n\n**Intinya:** ==Mulai dari pertanyaan terbuka untuk memperluas ruang cerita, lalu gunakan pertanyaan spesifik untuk menguji apakah ia benar-benar mengalami kejadian tersebut atau hanya menghafal skenario.==",
    "keyPoints": [
      "Hindari pertanyaan tertutup (Ya/Tidak) karena memberi jalan mudah bagi pembohong",
      "Gunakan Open-Ended Questions untuk memancing kronologi cerita yang panjang",
      "Gunakan Specific Questions (detail sensorik: musik, posisi duduk, suasana) untuk menguji ingatan nyata vs karangan"
    ]
