    "stageTitle": "18. [Pilar 4: Deteksi Kebohongan] Subtle Misquoting (Menguji Ketepatan Ingatan)",
    "content": "**🔗 Korelasi Lanjutan Verifikasi:** Setelah lawan bicara memaparkan kronologi dan detail lewat pertanyaan terbuka serta spesifik (Bagian 17), Anda dapat menguji konsistensi cerita tersebut secara halus menggunakan teknik **Subtle Misquoting**—yaitu sengaja mengulang pernyataan orang tersebut dengan sedikit perubahan detail untuk mengamati responsnya.\n\n**Contoh Kasus Nyata:** Di awal percakapan, seseorang mengatakan bahwa ia tiba di lokasi pada pukul **15.00**. Beberapa saat kemudian, Anda menyelipkan kalimat konfirmasi: *\"Jadi, kamu tadi sampai sekitar pukul **14.30**, benar?\"* Perhatikan reaksinya: apakah ia secara spontan mengoreksi (*\"Bukan, jam 15.00\"*) karena memiliki ingatan asli yang kuat, atau justru mengiyakan/membiarkan perubahan itu karena lupa dengan detail karangannya sendiri?\n\n**Intinya:** ==Subtle misquoting adalah alat uji konsistensi ingatan yang sangat efektif tanpa membuat lawan bicara merasa sedang diinterogasi, namun tetap bukan bukti tunggal kebohongan.==",
    "keyPoints": [
      "Ubah satu detail kecil (jam, warna, urutan kejadian) saat merangkum ucapan lawan bicara",
      "Orang yang mengalami kejadian nyata biasanya langsung mengoreksi secara refleks",
      "Orang yang mengarang cerita sering kali ragu atau ikut menyetujui detail yang sudah diubah karena beban mental"
    ]
