    "content": "Salah satu tantangan terbesar dalam K-Means adalah menentukan nilai $K$ yang optimal karena jumlah cluster tidak diketahui sebelumnya.\n\n**Elbow Method** memplot nilai *Within-Cluster Sum of Squares (WCSS)* atau inertia terhadap berbagai nilai $K$. Titik di mana penurunan inertia melambat drastis membentuk sudut siku (elbow), yang sering dijadikan acuan jumlah cluster terbaik.\n\n==Selain itu, Silhouette Score mengukur seberapa dekat suatu titik dengan cluster-nya sendiri dibandingkan dengan cluster tetangga terdekat, berkisar antara -1 hingga +1.== Nilai Silhouette yang tinggi menandakan partisi data terpisah dengan tegas.",
