    "stageTitle": "01. Spekulatif (Adjektiva)",
    "content": "Menurut KBBI, **spekulatif** (adjektiva) berarti ==berdasarkan dugaan atau perkiraan yang belum didukung bukti memadai==.\n\nKetika menganalisis keterbatasan informasi, kecenderungan penilaian, dan perubahan persepsi, penggunaan diksi **spekulatif** memberikan ketepatan makna: dapat digunakan untuk hipotesis awal, tetapi perlu dibedakan dari kesimpulan yang telah teruji.",
