    "stageTitle": "09. [Bab 5: Perbankan Modern] Bagaimana Bank Komersial Menciptakan Uang Saat Memberi Kredit",
    "content": "**🔗 Korelasi dari Uang Fiat ke Mesin Penciptaan Uang Hari Ini:** Di era uang fiat pasca-1971 (Bagian 08), siapa yang sebenarnya menciptakan sebagian besar uang yang beredar di masyarakat? Bukan sekadar mesin cetak pemerintah, melainkan **bank komersial setiap kali mereka menyetujui pinjaman (kredit)**.\n\n**Kesalahpahaman Umum tentang Bank:** Banyak orang mengira bank hanya bertindak sebagai perantara pasif:\n• **(1)** Nasabah A menabung uang.\n• **(2)** Bank menyimpan sebagian cadangan di brankas.\n• **(3)** Bank meminjamkan sisa tabungan Nasabah A tadi kepada Nasabah B.\n\nDalam sistem perbankan modern, cara kerjanya tidak sesederhana itu.\n\n**Mekanisme Nyata Penciptaan Uang Deposito (Contoh Pinjaman US$10.000):** Ketika seseorang mengajukan kredit **US$10.000** dan disetujui:\n• **(1)** Nasabah menandatangani kontrak utang tertulis.\n• **(2)** Bank mencatat kontrak pinjaman itu sebagai *aset* bank.\n• **(3)** Pada saat yang sama, bank mengetik dan mengkreditkan saldo deposito baru sebesar **US$10.000** ke rekening nasabah (dicatat sebagai *kewajiban* bank).\n• **(4)** Saldo baru tersebut langsung sah dipakai berbelanja di ekonomi nyata!\n\n**Catatan Batasan Penting:** Meskipun pemberian kredit menciptakan uang deposito baru (bukan sekadar memindahkan tabungan orang lain), **bank tidak bisa menciptakan uang tanpa batas**. Bank tetap dibatasi oleh aturan kecukupan modal (*capital adequacy*), cadangan likuiditas, regulasi bank sentral, risiko gagal bayar, dan penyelesaian pembayaran antarbank.\n\n**Intinya:** ==Dalam sistem perbankan modern, uang deposito baru tercipta ketika bank komersial memberikan kredit, meskipun kemampuan bank tersebut tetap dibatasi oleh modal, likuiditas, dan regulasi.==",
