    "stageTitle": "13. [Bab 6: Glosarium Inti] 12 Istilah Fondasi Sistem Moneter yang Wajib Dikuasai",
    "content": "**🔗 Korelasi Rangkuman Terminologi:** Untuk mengikat seluruh alur sejarah dari Bagian 01 hingga Bagian 12, berikut adalah **12 istilah kunci ekonomi dan moneter** yang menjadi fondasi pembahasan video ini:\n\n**1. Kelompok Sejarah & Standar Uang:**\n• **(a) Barter:** Pertukaran barang/jasa secara langsung tanpa menggunakan uang.\n• **(b) Gold Standard:** Sistem moneter yang mengaitkan nilai mata uang secara tetap dengan emas fisik.\n• **(c) Fiat Money:** Uang resmi yang nilainya tidak dijamin komoditas fisik seperti emas, melainkan oleh otoritas pemerintah dan kepercayaan publik.\n\n**2. Kelompok Perbankan & Penciptaan Uang:**\n• **(d) Debt:** Kewajiban kontraktual untuk membayar atau mengembalikan sesuatu.\n• **(e) Credit:** Fasilitas atau hubungan pemberian pinjaman antara kreditor dan debitor.\n• **(f) Fractional Reserve Banking:** Sistem perbankan yang hanya menyimpan sebagian kecil cadangan likuiditas dari total deposito nasabah.\n• **(g) Money Creation:** Proses penciptaan uang baru, terutama melalui pemberian kredit oleh bank komersial.\n• **(h) Monetary Policy:** Kebijakan bank sentral dalam mengatur suku bunga acuan dan jumlah uang beredar.\n\n**3. Kelompok Nilai & Daya Beli:**\n• **(i) Inflation:** Kenaikan tingkat harga barang dan jasa secara umum dari waktu ke waktu.\n• **(j) Purchasing Power:** Kemampuan daya beli nyata uang untuk membeli barang dan jasa.\n• **(k) Nominal Value:** Nilai uang yang tertera secara nominal angka di permukaan.\n• **(l) Real Value:** Nilai sebenarnya setelah memperhitungkan inflasi dan perubahan daya beli.\n\n**Intinya:** ==Menguasai perbedaan antara uang komoditas vs uang fiat, kredit vs penciptaan uang, serta nilai nominal vs nilai riil adalah kunci utama agar kita tidak buta terhadap cara kerja sistem keuangan modern.==",
